80	public class OwnerRestControllerV1 implements OwnersApi {
81	
82	    /** Maximum number of owners a single city may contain; creating an owner in a city that
83	     *  already has this many owners is rejected with 409 Conflict. */
84	    private static final int MAX_OWNERS_PER_CITY = 50;
85	
86	    /** When the owner's city already contains at least this many owners (but fewer than
87	     *  {@link #MAX_OWNERS_PER_CITY}, so the create is still allowed), the new owner's
88	     *  'capacityWarning' flag is set true to signal the city is approaching its capacity limit;
