91	
92	    /** Maximum number of owners that may be created on a single day (by registration date); creating
93	     *  an owner once this many owners already carry today's registration date is rejected with
94	     *  429 Too Many Requests. */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /** When more than this many owners already carry today's registration date at creation time, the
98	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
99	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
100	
101	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
102	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
103	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
104	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
105	
106	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
107	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
108	
109	    /** Serializes the immutable structured audit event emitted alongside the audit line. */
110	    private static final ObjectMapper AUDIT_EVENT_MAPPER = JsonMapper.builder().build();
111	
112	    /** Monotonically increasing sequence stamped on each structured {@code OWNER_CREATED} event,
113	     *  shared across all creates so the events carry a strict global order. */
114	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
115	
116	    private final ClinicService clinicService;
117	
118	    private final OwnerMapper ownerMapper;
119	
120	    private final PetMapper petMapper;
121	
122	    private final VisitMapper visitMapper;
123	
124	    private final TelephoneNormalizer telephoneNormalizer;
125	
126	    private final HouseholdNormalizer householdNormalizer;
127	
128	    private final AddressNormalizer addressNormalizer;
129	
130	    private final EmailNormalizer emailNormalizer;
131	
132	    /**
133	     * Records the owner created for each already-seen {@code Idempotency-Key}, so a create that
134	     * repeats with the same key returns the originally created owner (200) instead of creating a
135	     * duplicate. Keyed by the header value; concurrent because creates may be handled on any thread.
136	     */
137	    private final java.util.concurrent.ConcurrentMap<String, OwnerDto> idempotentCreates =
138	        new java.util.concurrent.ConcurrentHashMap<>();
139	
140	    public OwnerRestControllerV1(ClinicService clinicService,
141	                                 OwnerMapper ownerMapper,
142	                                 PetMapper petMapper,
143	                                 VisitMapper visitMapper,
144	                                 TelephoneNormalizer telephoneNormalizer,
145	                                 HouseholdNormalizer householdNormalizer,
146	                                 AddressNormalizer addressNormalizer,
147	                                 EmailNormalizer emailNormalizer) {
148	        this.clinicService = clinicService;
149	        this.ownerMapper = ownerMapper;
150	        this.petMapper = petMapper;
151	        this.visitMapper = visitMapper;
152	        this.telephoneNormalizer = telephoneNormalizer;
153	        this.householdNormalizer = householdNormalizer;
154	        this.addressNormalizer = addressNormalizer;
155	        this.emailNormalizer = emailNormalizer;
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
161	        Collection<Owner> owners;
162	        if (lastName != null) {
163	            owners = this.clinicService.findOwnerByLastName(lastName);
164	        } else {
165	            owners = this.clinicService.findAllOwners();
166	        }
167	        if (owners.isEmpty()) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
186	        // Idempotent create: when the request carries an 'Idempotency-Key' header that has already
187	        // been used for a successful create, return the originally created owner with 200 OK instead
188	        // of running the create pipeline again (which would otherwise reject the repeat as a duplicate
189	        // with 409). A first, unseen key runs the normal create and records its result under the key.
190	        String idempotencyKey = currentIdempotencyKey();
191	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
192	            return createOwner(ownerFieldsDto);
193	        }
194	        OwnerDto previouslyCreated = idempotentCreates.get(idempotencyKey);
195	        if (previouslyCreated != null) {
196	            return new ResponseEntity<>(previouslyCreated, HttpStatus.OK);
197	        }
198	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
199	        idempotentCreates.put(idempotencyKey, response.getBody());
200	        return response;
201	    }
202	
203	    /**
204	     * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
205	     * the request carries no such header (or there is no active servlet request). Reading it from the
206	     * request context here keeps the header — a request-level concern surrounding the create — out of
207	     * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
208	     *
209	     * @return the {@code Idempotency-Key} header value, or {@code null} when absent
210	     */
211	    private String currentIdempotencyKey() {
212	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
213	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
214	            return servletAttributes.getRequest().getHeader("Idempotency-Key");
215	        }
216	        return null;
217	    }
218	
219	    /**
220	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
221	     * response for the newly persisted owner: the request fields are mapped and normalized, every
222	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
223	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
224	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
225	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
226	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
227	     * {@code addOwner} without disturbing the creation steps gathered here.
228	     *
229	     * @param ownerFieldsDto the submitted owner fields
230	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
231	     */
232	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
233	        HttpHeaders headers = new HttpHeaders();
234	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
235	        normalizeOwnerFields(owner);
236	        // Enforce the pre-persistence policies that can reject the new owner outright.
237	        rejectDisallowedOwnerCreation(owner);
238	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
239	        // function of last name and postcode), cap the membership level for a new household member,
240	        // and record the household size. The household id is no longer part of the identity key, so
241	        // this no longer rejects a household duplicate: owners sharing a household are distinguished
242	        // by the identity-key check below and otherwise flagged as soft duplicates.
243	        boolean declaredHouseholdMember =
244	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
245	        // Reject the create when the owner's whole derived identity key (the SHA-256 over normalized
246	        // telephone, lower-cased email and the Soundex of the last name) already matches an existing
247	        // owner. This single rule subsumes the former separate telephone, email and household
248	        // duplicate checks.
249	        rejectWhenIdentityInUse(owner);
250	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
251	        // shares an existing owner's last name and postcode with a different telephone. A declared
252	        // household member is never flagged: it is a known member, not a suspected duplicate.
253	        assignPossibleDuplicate(owner, declaredHouseholdMember);
254	        // Assign the remaining create-time derived fields (namesake count, member id
255	        // and bulk-signup warning), each fixed at creation time.
256	        assignDerivedFields(owner);
257	        // Assign the (household-capped) membership level, fixed at creation time. This runs after the
258	        // derived fields above because the level is computed from the membership points, which depend
259	        // on the namesake count assigned in assignDerivedFields.
260	        assignMembershipLevel(owner);
261	        this.clinicService.saveOwner(owner);
262	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
263	        // Record the successful create on the dedicated AUDIT log.
264	        auditOwnerCreated(owner, ownerDto);
265	        headers.setLocation(UriComponentsBuilder.newInstance()
266	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
267	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
268	    }
269	
270	    /**
271	     * Emits the audit line recording a successful owner create on the dedicated {@code AUDIT} log,
272	     * carrying the owner id, its current primary identifier (see {@link #primaryIdentifier}), the
273	     * registration date and membership level so the create can be traced. Keeping
274	     * the audit emission in its own helper leaves {@link #createOwner} a thin pipeline and gives the
275	     * create's audit side-effects a single home, so a further audit side-effect of a create is added
276	     * here (or as a sibling helper) rather than inline in the pipeline.
277	     *
278	     * @param owner    the persisted owner
279	     * @param ownerDto the mapped view of the persisted owner, source of the membership fields
280	     */
281	    private void auditOwnerCreated(Owner owner, OwnerDto ownerDto) {
282	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
283	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
284	            ownerDto.getMembershipLevel());
285	        auditOwnerCreatedEvent(owner, ownerDto);
286	    }
287	
288	    /**
289	     * Emits the immutable structured {@code OWNER_CREATED} event on the {@code AUDIT} log as a JSON
290	     * object {@code {seq, ownerId, memberId, membershipLevel, event}}. The {@code seq} is a
291	     * strictly increasing integer across every create (see {@link #OWNER_CREATED_SEQUENCE}), giving
292	     * the events a total order. The identifier field carries the owner's current primary identifier
293	     * (see {@link #primaryIdentifier}) — the member id — so every audit consumer follows the primary
294	     * identifier by changing only {@link #primaryIdentifier}.
295	     *
296	     * @param owner    the persisted owner
297	     * @param ownerDto the mapped view of the persisted owner, source of the membership level
298	     */
299	    private void auditOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
300	        OwnerCreatedEvent event = new OwnerCreatedEvent(
301	            OWNER_CREATED_SEQUENCE.incrementAndGet(), owner.getId(), primaryIdentifier(owner),
302	            ownerDto.getMembershipLevel(), "OWNER_CREATED");
303	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
304	    }
305	
306	    /**
307	     * The immutable structured audit event published for a successful owner create. Its
308	     * {@code memberId} field carries the owner's current primary identifier (see
309	     * {@link #primaryIdentifier}), so the same event shape follows the identifier as it changes.
310	     */
311	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
312	        Integer membershipLevel, String event) {
313	    }
314	
315	    /**
316	     * Returns the owner's current primary identifier: the single value that identifies the owner in
317	     * the audit trail and in any audit side-effect of a create. This is the member id; resolving it
318	     * through one accessor means that if the primary identifier is later changed every audit consumer
319	     * follows the new identifier by changing only this method.
320	     *
321	     * @param owner the owner whose primary identifier is required
322	     * @return the owner's current primary identifier
323	     */
324	    private String primaryIdentifier(Owner owner) {
325	        return owner.getMemberId();
326	    }
327	
328	    /**
329	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
330	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
331	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
332	     * the sequence of create-time rejections stays readable and a new rule is added as one more
333	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
334	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
335	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}.
336	     *
337	     * @param owner the newly mapped and normalized owner being created
338	     */
339	    private void rejectDisallowedOwnerCreation(Owner owner) {
340	        rejectWhenDailyLimitReached(owner);
341	        rejectWhenCityAtCapacity(owner);
342	    }
343	
344	    /**
345	     * Applies the household-membership rules for a newly normalized owner being created. The
346	     * household id is a deterministic function of the owner's last name and postcode, so owners
347	     * with the same last name and postcode share it automatically; it is assigned to the new owner
348	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
349	     * same last name and postcode is a member of the same household. A new owner may join an
350	     * existing household: rather than the create being rejected, the newcomer's membership level is
351	     * capped at one above the household's current maximum (see {@link #assignMembershipLevel}). When
352	     * the request declares it shares the household via {@code sharesHousehold} the owner is a known,
353	     * declared member and is never flagged as a possible duplicate. The owner's
354	     * {@code householdSize} (the number of owners sharing the household after this create) is
355	     * recorded either way.
356	     *
357	     * @param owner           the newly mapped and normalized owner being created
358	     * @param sharesHousehold whether the request declared that the owner shares an existing household
359	     * @return {@code true} if the owner joined an existing household as a declared member
360	     */
361	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
362	        // Assign the deterministic household id (a pure function of last name and postcode) so every
363	        // owner with the same last name and postcode shares it automatically.
364	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
365	        // Identify any existing owners in the same household (same computed household id). A new owner
366	        // may join an existing household: its membership level is capped at one above the household's
367	        // current maximum (see assignMembershipLevel) rather than the create being rejected outright.
368	        List<Owner> householdMembers = sameHouseholdOwners(owner);
369	        // An owner that joins an existing household while the request declares it shares that
370	        // household is a known, declared member and so is never flagged as a possible duplicate.
371	        boolean declaredHouseholdMember = !householdMembers.isEmpty() && sharesHousehold;
372	        // Record the size of this owner's household after this create, fixed at creation time.
373	        owner.setHouseholdSize(householdMembers.size() + 1);
374	        return declaredHouseholdMember;
375	    }
376	
377	    /**
378	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
379	     * has already been resolved: the namesake count, the per-city member id, the bulk-signup warning
380	     * flag and the city capacity warning flag. Each value is fixed at creation time and is
381	     * independent of the others. Grouping them
382	     * here keeps {@link #addOwner} focused on the high-level create sequence.
383	     *
384	     * @param owner the owner being created, already normalized and with its household resolved
385	     */
386	    private void assignDerivedFields(Owner owner) {
387	        // Record how many existing owners already share this owner's first and last name
388	        // (compared case-insensitively) before this create, fixed at creation time.
389	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
390	        // Assign the member id '<REGION><FY><HASH8><CHK>' from the region derived from the postcode,
391	        // the 2-digit fiscal year of the registration date, an 8-hex-character hash of the normalized
392	        // telephone and last name, and a Luhn check digit over the preceding digits, fixed at
393	        // creation time.
394	        owner.setMemberId(memberId(owner));
395	        // Flag the create when more than 80 owners have already been created on this owner's
396	        // (adjusted business-day) registration date, fixed at creation time.
397	        owner.setBulkSignupWarning(
398	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
399	        // Flag the create when the owner's city is approaching its capacity limit: it already holds
400	        // between CAPACITY_WARNING_THRESHOLD and MAX_OWNERS_PER_CITY - 1 owners (40-49). A city at or
401	        // over the limit is rejected earlier (see rejectWhenCityAtCapacity), so this is never reached
402	        // for a full city. Fixed at creation time.
403	        int cityOwners = countOwnersInCity(owner.getCity());
404	        owner.setCapacityWarning(
405	            cityOwners >= CAPACITY_WARNING_THRESHOLD && cityOwners < MAX_OWNERS_PER_CITY);
406	    }
407	
408	    /**
409	     * Assigns the new owner's membership level, capped by their household, and fixes it at creation
410	     * time. The level a newly created owner would earn from their membership points cannot exceed
411	     * one above the current maximum membership level among their existing household members (the
412	     * owners already sharing this owner's household id); the capped value is stored so it is returned
413	     * unchanged on later reads. When the owner has no existing household member no cap applies and
414	     * the plain points-derived level is used.
415	     *
416	     * @param owner the owner being created, already normalized and with its derived fields assigned
417	     */
418	    private void assignMembershipLevel(Owner owner) {
419	        int level = ownerMapper.membershipLevel(ownerMapper.membershipPoints(owner));
420	        List<Owner> householdMembers = sameHouseholdOwners(owner);
421	        if (!householdMembers.isEmpty()) {
422	            int maxMemberLevel = householdMembers.stream()
423	                .mapToInt(this::memberLevel)
424	                .max()
425	                .getAsInt();
426	            level = Math.min(level, maxMemberLevel + 1);
427	        }
428	        owner.setMembershipLevel(level);
429	    }
430	
431	    /**
432	     * Returns an existing household member's membership level for the purpose of capping a new
433	     * member's level: the level stored on the member when present (the already-capped value fixed at
434	     * its own creation), otherwise the level derived from its membership points (for members created
435	     * before the level was persisted).
436	     *
437	     * @param member an existing owner in the same household
438	     * @return the member's membership level
439	     */
440	    private int memberLevel(Owner member) {
441	        return member.getMembershipLevel() != null
442	            ? member.getMembershipLevel()
443	            : ownerMapper.membershipLevel(ownerMapper.membershipPoints(member));
444	    }
