446	    /**
447	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
448	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) is the SHA-256 hex over
449	     * the normalized telephone, the lower-cased email (or empty) and the Soundex of the last name, so
450	     * this single rule replaces the former separate telephone, email and household duplicate checks:
451	     * two owners collide only when their whole keys are equal, and members of one household with
452	     * different telephones have different keys and are both allowed (instead flagged as soft
453	     * duplicates).
454	     *
455	     * @param owner the owner being created, already normalized
456	     */
457	    private void rejectWhenIdentityInUse(Owner owner) {
458	        String identityKey = owner.getIdentityKey();
459	        boolean inUse = existingOwners()
460	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
461	        if (inUse) {
462	            throw new DuplicateIdentityException(
463	                "An owner with identity key " + identityKey + " already exists");
464	        }
465	    }
466	
467	    /**
468	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
469	     * duplicate (identity-key) check. When an existing owner has a different identity key but shares
470	     * this owner's postcode and the Soundex code of its last name, the new owner is still created but
471	     * flagged as a possible duplicate: {@code possibleDuplicate} is set true and
472	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
473	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
474	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
475	     * possible duplicate. A declared household member is never flagged: it is a known member of the
476	     * household, not a suspected duplicate. Both values are fixed at creation time.
477	     *
478	     * @param owner                   the owner being created, already normalized and confirmed not a
479	     *                                hard duplicate
480	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
481	     *                                member
482	     */
483	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
484	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
485	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
486	            .map(Owner::getId)
487	            .min(Integer::compareTo)
488	            .orElse(null);
489	        owner.setPossibleDuplicate(matchId != null);
490	        owner.setPossibleDuplicateOf(matchId);
491	    }
492	
493	    /**
494	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
495	     * two have different identity keys (an equal key would already have been rejected as a hard
496	     * duplicate) but share a postcode (required on both sides, so an owner without a postcode never
497	     * matches) and the Soundex code of their last name. A match flags the new owner as a possible
498	     * duplicate of the existing one without rejecting the create.
499	     *
500	     * @param existing an existing owner to compare against
501	     * @param owner    the owner being created
502	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
503	     */
504	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
505	        return existing.getPostcode() != null
506	            && existing.getPostcode().equals(owner.getPostcode())
507	            && Soundex.encode(existing.getLastName()).equals(Soundex.encode(owner.getLastName()))
508	            && !existing.getIdentityKey().equals(owner.getIdentityKey());
509	    }
