511	    /**
512	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
513	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
514	     *
515	     * @param owner the owner being created
516	     */
517	    private void rejectWhenDailyLimitReached(Owner owner) {
518	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
519	            throw new DailyOwnerLimitExceededException(
520	                "The maximum number of owners that may be created today has already been reached");
521	        }
522	    }
523	
524	    /**
525	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
526	     * or more owners, with 409 Conflict.
527	     *
528	     * @param owner the owner being created
529	     */
530	    private void rejectWhenCityAtCapacity(Owner owner) {
531	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
532	            throw new CityCapacityExceededException(
533	                "The city " + owner.getCity() + " already contains the maximum number of owners");
534	        }
535	    }
