537	    /**
538	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
539	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
540	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
541	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
542	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
543	     * server's current date. Canonicalising the address here, before the household checks read it,
544	     * ensures duplicate detection and the shared household id both compare the normalized form.
545	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
546	     * duplicate, household and member-id rules.
547	     *
548	     * @param owner the newly mapped owner to canonicalize
549	     */
550	    private void normalizeOwnerFields(Owner owner) {
551	        // Canonicalize the owner's address fields on create so the address is stored and returned in
552	        // canonical form and every later comparison (household duplicate detection and the shared
553	        // household id) uses it. A value that is blank after normalization is rejected with 400.
554	        normalizeAddressFields(owner);
555	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
556	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
557	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
558	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
559	        // Store the (already syntactically validated) email lower-cased so it is persisted and
560	        // returned in canonical form. A missing email is left untouched.
561	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
562	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
563	        // canonicalization so the comparison sees the lower-cased value.
564	        rejectDisposableEmailDomain(owner.getEmail());
565	        // Validate the optional postcode against the fixed range for the city's region. A postcode
566	        // is checked only when present (it is optional); one out of range for the city's region is
567	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
568	        // value is left unchanged.
569	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
570	        // Reject a supplied registration date that is later than the server's current date with
571	        // 400, before any defaulting or business-day adjustment, so a future date is never
572	        // persisted regardless of how the roll-forward would move it.
573	        rejectFutureRegistrationDate(owner.getRegistrationDate());
574	        // Default the registration date to the server's current date when the client did not
575	        // supply one, then roll the effective date forward to a business day so a Saturday or
576	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
577	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
578	        // date-derived field (such as the member id's fiscal-year segment) and the per-day
579	        // create-limit are computed from.
580	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
581	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
582	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
583	    }
584	
585	    /**
586	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
587	     * returned in canonical form. The owner may supply its address in either of two forms and the
588	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
589	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
590	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
591	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
592	     * stored {@code address} is composed from the normalized structured lines when present — the
593	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
594	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
595	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
596	     * here, before the household checks read it, ensures duplicate detection and the shared household
597	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
598	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
599	     *
600	     * @param owner the newly mapped owner whose address is canonicalized
601	     */
602	    private void normalizeAddressFields(Owner owner) {
603	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
604	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
605	            owner.setAddressLine1(line1);
606	            String composed = line1;
607	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
608	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
609	                owner.setAddressLine2(line2);
610	                composed = line1 + " " + line2;
611	            }
612	            owner.setAddress(composed);
613	        }
614	        else {
615	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
616	        }
617	    }
618	
619	    /**
620	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
621	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
622	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
623	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
624	     * domain part is left untouched.
625	     *
626	     * @param email the owner's canonicalized email, or {@code null} when absent
627	     */
628	    private void rejectDisposableEmailDomain(String email) {
629	        if (email == null) {
630	            return;
631	        }
632	        int at = email.lastIndexOf('@');
633	        if (at < 0) {
634	            return;
635	        }
636	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
637	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
638	            throw new DisposableEmailException(
639	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
640	        }
641	    }
642	
643	    /**
644	     * Rejects a supplied registration date that is later than the server's current date with a
645	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
646	     * accepted, and a date on or before today is left for the normal defaulting and business-day
647	     * adjustment.
648	     *
649	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
650	     */
651	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
652	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
653	            throw new InvalidRegistrationDateException(
654	                "The supplied registration date " + registrationDate + " is later than the current date");
655	        }
656	    }
