658	    /**
659	     * The fixed list of public holidays. A registration date that lands on one of these dates is
660	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
661	     */
662	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
663	        java.time.LocalDate.of(2026, 1, 1),
664	        java.time.LocalDate.of(2026, 1, 26),
665	        java.time.LocalDate.of(2026, 4, 25),
666	        java.time.LocalDate.of(2026, 12, 25),
667	        java.time.LocalDate.of(2026, 12, 28));
668	
669	    /**
670	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
671	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
672	     * unchanged. Applied to the effective registration date (whether supplied in the request or
673	     * defaulted to the server date) so the persisted registration date, every value derived from it
674	     * and the per-day create-limit all use the adjusted business day.
675	     *
676	     * @param date the effective registration date
677	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
678	     */
679	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
680	        java.time.LocalDate adjusted = date;
681	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
682	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
683	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
684	            adjusted = adjusted.plusDays(1);
685	        }
686	        return adjusted;
687	    }
688	
689	    /**
690	     * Builds the member id '<REGION><FY><HASH8><CHK>' for a newly created owner, where REGION is the
691	     * region derived from the owner's postcode (falling back to the city, via
692	     * {@link LocalityResolver}), FY is the last two digits of the fiscal year of the
693	     * (business-day-adjusted) registration date, HASH8 is the first 8 upper-case hex characters of
694	     * the SHA-256 digest over the owner's normalized telephone concatenated with the last name, and
695	     * CHK is a single Luhn check digit over the decimal digits of '<REGION><FY><HASH8>' (e.g.
696	     * 'NSW26A1B2C3D45'). When that base id already belongs to an existing owner, '-<n>' is appended
697	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
698	     * distinct member ids.
699	     *
700	     * @param owner the owner being created, already normalized
701	     * @return the formatted, de-duplicated member id
702	     */
703	    private String memberId(Owner owner) {
704	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
705	        String fy = String.format("%02d",
706	            org.springframework.samples.petclinic.util.FiscalYear.of(owner.getRegistrationDate()) % 100);
707	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
708	        String base = MemberId.format(region, fy, hash8);
709	        return deduplicateCode(base, existingMemberIds());
710	    }
711	
712	    /**
713	     * Collects the member ids already assigned to existing owners, the set a newly built id is
714	     * de-duplicated against. Gathering them here keeps {@link #memberId} focused on building the
715	     * id and lets the uniqueness step (see {@link #deduplicateCode}) work against the ids alone.
716	     *
717	     * @return the member ids currently in use
718	     */
719	    private Set<String> existingMemberIds() {
720	        return existingOwners()
721	            .map(Owner::getMemberId)
722	            .filter(id -> id != null)
723	            .collect(Collectors.toSet());
724	    }
725	
726	    /**
727	     * Returns a unique code for a newly built base identifier: the base itself when it is not already
728	     * taken, otherwise the base with {@code "-<n>"} appended, using the smallest {@code n} of 2 or
729	     * more that makes it unique. Keeping the collision rule in its own helper leaves the identifier's
730	     * construction to its builder and gives the "make it unique" step a single home independent of
731	     * which identifier is being assigned.
732	     *
733	     * @param base  the freshly built identifier, before any uniqueness suffix
734	     * @param taken the identifiers already in use
735	     * @return {@code base} when unused, otherwise the smallest {@code base + "-" + n} not in {@code taken}
736	     */
737	    private String deduplicateCode(String base, Set<String> taken) {
738	        if (!taken.contains(base)) {
739	            return base;
740	        }
741	        int n = 2;
742	        while (taken.contains(base + "-" + n)) {
743	            n++;
744	        }
745	        return base + "-" + n;
746	    }
