748	    /**
749	     * Streams the existing owners that the create-time rules match a new owner against. Every
750	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
751	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
752	     * own matching criterion rather than on how the existing owners are retrieved.
753	     *
754	     * @return a stream over all existing owners
755	     */
756	    private Stream<Owner> existingOwners() {
757	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
758	        // new create, so the duplicate, identity and household checks (and the other create-time
759	        // scans built on this helper) ignore it.
760	        return this.clinicService.findAllOwners().stream()
761	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
762	    }
763	
764	    /**
765	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
766	     * enforce the per-city capacity limit and fix an owner's capacity-warning flag at creation time.
767	     *
768	     * @param city the city of the owner being created
769	     * @return the number of existing owners in a matching city
770	     */
771	    private int countOwnersInCity(String city) {
772	        return (int) existingOwners()
773	            .filter(existing -> existing.getCity() != null
774	                && existing.getCity().equalsIgnoreCase(city))
775	            .count();
776	    }
777	
778	    /**
779	     * Counts the existing owners whose registration date is the given adjusted business day. Used
780	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
781	     * owners already carry that business day as their registration date.
782	     *
783	     * @param date the adjusted business-day registration date to match
784	     * @return the number of existing owners registered on that date
785	     */
786	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
787	        return (int) existingOwners()
788	            .filter(existing -> date.equals(existing.getRegistrationDate()))
789	            .count();
790	    }
791	
792	    /**
793	     * Returns the existing owners in the given owner's household, i.e. those sharing its
794	     * deterministic household id (the same last name and postcode). The id is computed via
795	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
796	     * whitespace are treated as the same household. Centralising how "the same household" is matched
797	     * here keeps that definition in one place for every caller.
798	     *
799	     * @param owner the owner being created, with its household id already assigned
800	     * @return the existing owners in the owner's household (possibly empty)
801	     */
802	    private List<Owner> sameHouseholdOwners(Owner owner) {
803	        String householdId = owner.getHouseholdId();
804	        return existingOwners()
805	            .filter(existing -> householdId.equals(
806	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
807	            .toList();
808	    }
