810	    /**
811	     * Counts the existing owners who share the given first and last name, compared
812	     * case-insensitively. Used to fix an owner's namesake count at creation time.
813	     *
814	     * @param firstName the first name of the owner being created
815	     * @param lastName  the last name of the owner being created
816	     * @return the number of existing owners with a matching first and last name
817	     */
818	    private int countNamesakes(String firstName, String lastName) {
819	        return (int) existingOwners()
820	            .filter(existing -> existing.getFirstName() != null
821	                && existing.getFirstName().equalsIgnoreCase(firstName)
822	                && existing.getLastName() != null
823	                && existing.getLastName().equalsIgnoreCase(lastName))
824	            .count();
825	    }
826	
827	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
828	    @Override
829	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
830	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
831	        if (currentOwner == null) {
832	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
833	        }
834	        currentOwner.setAddress(ownerFieldsDto.getAddress());
835	        currentOwner.setCity(ownerFieldsDto.getCity());
836	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
837	        currentOwner.setLastName(ownerFieldsDto.getLastName());
838	        // Normalize the telephone to canonical E.164 form so it is stored and returned
839	        // consistently with create; an unformattable value is rejected with 400.
840	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
841	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
842	        this.clinicService.saveOwner(currentOwner);
843	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
844	    }
845	
846	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
847	    @Transactional
848	    @Override
849	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
850	        Owner owner = this.clinicService.findOwnerById(ownerId);
851	        if (owner == null) {
852	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
853	        }
854	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
855	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
856	        // duplicate and identity checks (see existingOwners()).
857	        owner.setDeleted(true);
858	        this.clinicService.saveOwner(owner);
859	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
860	    }
861	
862	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
863	    @Override
864	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
865	        Owner owner = this.clinicService.findOwnerById(ownerId);
866	        if (owner == null) {
867	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
868	        }
869	        HttpHeaders headers = new HttpHeaders();
870	        Pet pet = petMapper.toPet(petFieldsDto);
871	        owner.setId(ownerId);
872	        pet.setOwner(owner);
873	        pet.getType().setName(null);
874	        this.clinicService.savePet(pet);
875	        PetDto petDto = petMapper.toPetDto(pet);
876	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
877	            .buildAndExpand(pet.getId()).toUri());
878	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
879	    }
880	
881	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
882	    @Override
883	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
884	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
885	        if (currentOwner != null) {
886	            Pet currentPet = this.clinicService.findPetById(petId);
887	            if (currentPet != null) {
888	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
889	                currentPet.setName(petFieldsDto.getName());
890	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
891	                this.clinicService.savePet(currentPet);
892	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
893	            }
894	        }
895	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
896	    }
897	
898	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
899	    @Override
900	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
901	        HttpHeaders headers = new HttpHeaders();
902	        Visit visit = visitMapper.toVisit(visitFieldsDto);
903	        Pet pet = new Pet();
904	        pet.setId(petId);
905	        visit.setPet(pet);
906	        this.clinicService.saveVisit(visit);
907	        VisitDto visitDto = visitMapper.toVisitDto(visit);
908	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
909	            .buildAndExpand(visit.getId()).toUri());
910	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
911	    }
912	
913	
914	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
915	    @Override
916	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
917	        Owner owner = this.clinicService.findOwnerById(ownerId);
918	        if (owner != null) {
919	            Pet pet = owner.getPet(petId);
920	            if (pet != null) {
921	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
922	            }
923	        }
924	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
925	    }
926	}
